// ════════════════════════════════════════════════════════════════════════════
// Native oracles (independent of the slice/mirror code paths).
// ════════════════════════════════════════════════════════════════════════════

/// clean-kernel expr/meta.rs mix_hash — VERBATIM.
fn native_mix_hash(h: u64, k: u64) -> u64 {
    const M: u64 = 0xc6a4_a793_5bd1_e995;
    const R: u32 = 47;
    let mut k = k.wrapping_mul(M);
    k ^= k >> R;
    k ^= M;
    let h = h ^ k;
    h.wrapping_mul(M)
}

/// clean-kernel murmur_hash_64a in the PRODUCTION block form (as-chunks ≡
/// chunks_exact(8) + remainder) — the modules carry the index-loop
/// transcription, so agreement proves [T-murmur-idx] on every tested name.
fn native_murmur_hash_64a(data: &[u8], seed: u64) -> u64 {
    const M: u64 = 0xc6a4_a793_5bd1_e995;
    const R: u32 = 47;
    let len = data.len();
    let mut h: u64 = seed ^ (len as u64).wrapping_mul(M);
    let mut chunks = data.chunks_exact(8);
    for block in &mut chunks {
        let mut k = u64::from_le_bytes(block.try_into().expect("8-byte chunk"));
        k = k.wrapping_mul(M);
        k ^= k >> (R & 63);
        k = k.wrapping_mul(M);
        h ^= k;
        h = h.wrapping_mul(M);
    }
    let tail = chunks.remainder();
    for (i, &b) in tail.iter().enumerate() {
        h ^= (b as u64) << (i.wrapping_mul(8) & 63);
    }
    if !tail.is_empty() {
        h = h.wrapping_mul(M);
    }
    h ^= h >> (R & 63);
    h = h.wrapping_mul(M);
    h ^= h >> (R & 63);
    h
}

/// A decoded Name component, leaf-to-root.
#[derive(Debug, Clone, PartialEq, Eq)]
enum Comp {
    Str(Vec<u8>),
    Num(u64),
}

/// Native `from_string_uncached` with the REAL `split('.')` + REAL
/// `str::parse::<u64>()` (production name.rs:557-565): (leaf-to-root comps,
/// cached_hash).
fn native_from_string_uncached(s: &str) -> (Vec<Comp>, u64) {
    let mut comps_root_to_leaf: Vec<Comp> = Vec::new();
    let mut h: u64 = 1723; // anon
    for part in s.split('.') {
        if let Ok(n) = part.parse::<u64>() {
            h = native_mix_hash(h, n);
            comps_root_to_leaf.push(Comp::Num(n));
        } else {
            h = native_mix_hash(h, native_murmur_hash_64a(part.as_bytes(), 11));
            comps_root_to_leaf.push(Comp::Str(part.as_bytes().to_vec()));
        }
    }
    let mut leaf_to_root = comps_root_to_leaf;
    leaf_to_root.reverse();
    (leaf_to_root, h)
}

// GOLDEN constants from the REAL clean-kernel binary (pinned in R4-R6; see
// e2e_universe_realnames.rs module docs for the pin recipe).
const GOLDEN_U: u64 = 0xae572a66f1f7b2e8;
const GOLDEN_V: u64 = 0x486e7075aebc6ca6;
const GOLDEN_NAT: u64 = 0x9ecc0d3a68dfdd9b;
const GOLDEN_AX_DUP: u64 = 0xfdb31ca9d0ac3c36;
const GOLDEN_THM42: u64 = 0xdcaef40c027c85c5;
const GOLDEN_ANON: u64 = 1723;

// ── the JIT-side raw Name decode (offsets identical to rounds 4-6) ──────────

/// Walk a JIT-built Name at `ptr`: returns (leaf-to-root comps, root hash,
/// per-node hashes leaf-to-root). Panics on an unknown tag (fail-loud decode).
unsafe fn decode_jit_name(ptr: *const u8) -> (Vec<Comp>, u64, Vec<u64>) {
    unsafe {
        let mut comps = Vec::new();
        let mut node_hashes = Vec::new();
        let read_u64 = |p: *const u8| -> u64 { (p as *const u64).read_unaligned() };
        let read_ptr = |p: *const u8| -> *const u8 { (p as *const *const u8).read_unaligned() };
        let root_hash = read_u64(ptr.add(32));
        let mut cur = ptr;
        loop {
            let tag = read_u64(cur);
            node_hashes.push(read_u64(cur.add(32)));
            match tag {
                0 => break,
                1 => {
                    let parent_inner = read_ptr(cur.add(8));
                    let s_inner = read_ptr(cur.add(16));
                    let s_len = read_u64(cur.add(24)) as usize;
                    let bytes = std::slice::from_raw_parts(s_inner.add(16), s_len).to_vec();
                    comps.push(Comp::Str(bytes));
                    cur = parent_inner.add(16);
                }
                2 => {
                    let n = read_u64(cur.add(8));
                    let parent_inner = read_ptr(cur.add(16));
                    comps.push(Comp::Num(n));
                    cur = parent_inner.add(16);
                }
                t => panic!("decode_jit_name: unknown NameInner tag {t} (layout drift?)"),
            }
        }
        (comps, root_hash, node_hashes)
    }
}

/// Recompute the production hash chain from decoded comps (leaf-to-root):
/// per-node hashes leaf-to-root INCLUDING the final Anon node (1723).
fn recompute_hash_chain(comps: &[Comp]) -> Vec<u64> {
    let mut fwd = vec![1723u64];
    for c in comps.iter().rev() {
        let prev = *fwd.last().unwrap();
        let h = match c {
            Comp::Str(b) => native_mix_hash(prev, native_murmur_hash_64a(b, 11)),
            Comp::Num(n) => native_mix_hash(prev, *n),
        };
        fwd.push(h);
    }
    fwd.reverse();
    fwd
}

/// SAFE walk of a HOST-built (mirror) Name: (leaf-to-root comps, root hash).
fn native_name_comps(n: &rn::Name) -> (Vec<Comp>, u64) {
    let mut comps = Vec::new();
    let mut cur = n;
    loop {
        match &cur.inner {
            rn::NameInner::Anon => break,
            rn::NameInner::Str(p, s) => {
                comps.push(Comp::Str(s.as_bytes().to_vec()));
                cur = &**p;
            }
            rn::NameInner::Num(p, v) => {
                comps.push(Comp::Num(*v));
                cur = &**p;
            }
        }
    }
    (comps, n.cached_hash)
}

// ════════════════════════════════════════════════════════════════════════════
// The asymmetric deep comparators (R6 pattern): native side walked SAFELY via
// mirror types, JIT side Names decoded RAW with the per-node hash chain
// REVALIDATED on every comparison. Meta words compared bit-exact per node.
// ════════════════════════════════════════════════════════════════════════════

fn name_eq_nj(native: &rn::Name, jit: &rn::Name) -> bool {
    let (ncomps, nhash) = native_name_comps(native);
    let (jcomps, jhash, jchain) = unsafe { decode_jit_name(jit as *const rn::Name as *const u8) };
    let expect_chain = recompute_hash_chain(&jcomps);
    assert_eq!(
        jchain, expect_chain,
        "JIT Name per-node hash chain != production recompute (layout drift or hash bug?)"
    );
    ncomps == jcomps && nhash == jhash
}

fn level_eq_nj(native: &rn::Level, jit: &rn::Level) -> bool {
    match (native, jit) {
        (rn::Level::Zero, rn::Level::Zero) => true,
        (rn::Level::Succ(a), rn::Level::Succ(b)) => level_eq_nj(a, b),
        (rn::Level::Max(a1, b1), rn::Level::Max(a2, b2)) => {
            level_eq_nj(a1, a2) && level_eq_nj(b1, b2)
        }
        (rn::Level::IMax(a1, b1), rn::Level::IMax(a2, b2)) => {
            level_eq_nj(a1, a2) && level_eq_nj(b1, b2)
        }
        (rn::Level::Param(a), rn::Level::Param(b)) => name_eq_nj(a, b),
        _ => false,
    }
}

fn levels_eq_nj(native: &[rn::Level], jit: &[rn::Level]) -> bool {
    if native.len() != jit.len() {
        return false;
    }
    native
        .iter()
        .zip(jit.iter())
        .all(|(a, b)| level_eq_nj(a, b))
}

/// Deep native==JIT comparison: meta word BIT-IDENTICAL at every node, then
/// structural with production-name comparison at every Name site. FVar nodes
/// compare by id — the FRESHNESS OBSERVABLE.
fn deep_eq_nj(native: &rn::Expr, jit: &rn::Expr) -> bool {
    if native.meta.raw() != jit.meta.raw() {
        return false;
    }
    match (&native.kind, &jit.kind) {
        (rn::ExprKind::BVar(x), rn::ExprKind::BVar(y)) => x == y,
        (rn::ExprKind::FVar(x), rn::ExprKind::FVar(y)) => x == y,
        (rn::ExprKind::Lit(x), rn::ExprKind::Lit(y)) => x == y,
        (rn::ExprKind::Sort(x), rn::ExprKind::Sort(y)) => level_eq_nj(x, y),
        (rn::ExprKind::Const(n1, l1), rn::ExprKind::Const(n2, l2)) => {
            name_eq_nj(n1, n2) && levels_eq_nj(l1, l2)
        }
        (rn::ExprKind::App(f1, a1), rn::ExprKind::App(f2, a2)) => {
            deep_eq_nj(f1, f2) && deep_eq_nj(a1, a2)
        }
        (rn::ExprKind::Lam(b1, t1, y1), rn::ExprKind::Lam(b2, t2, y2)) => {
            b1 == b2 && deep_eq_nj(t1, t2) && deep_eq_nj(y1, y2)
        }
        (rn::ExprKind::Pi(b1, t1, y1), rn::ExprKind::Pi(b2, t2, y2)) => {
            b1 == b2 && deep_eq_nj(t1, t2) && deep_eq_nj(y1, y2)
        }
        (rn::ExprKind::Let(n1, t1, v1, y1, d1), rn::ExprKind::Let(n2, t2, v2, y2, d2)) => {
            name_eq_nj(n1, n2)
                && deep_eq_nj(t1, t2)
                && deep_eq_nj(v1, v2)
                && deep_eq_nj(y1, y2)
                && d1 == d2
        }
        (rn::ExprKind::Proj(n1, i1, e1), rn::ExprKind::Proj(n2, i2, e2)) => {
            name_eq_nj(n1, n2) && i1 == i2 && deep_eq_nj(e1, e2)
        }
        (rn::ExprKind::MData(m1, e1), rn::ExprKind::MData(m2, e2)) => {
            m1 == m2 && deep_eq_nj(e1, e2)
        }
        _ => false,
    }
}

/// R8 discriminants — the slice TypeError now carries UnknownFVar in the
/// production position (right after UnboundVariable).
fn type_error_disc(e: &rn::TypeError) -> u8 {
    match e {
        rn::TypeError::UnboundVariable(_) => 0,
        rn::TypeError::UnknownFVar(_) => 1,
        rn::TypeError::UnknownConst(_) => 2,
        rn::TypeError::TypeMismatch { .. } => 3,
        rn::TypeError::NotAPi { .. } => 4,
        rn::TypeError::ExpectedSort { .. } => 5,
        rn::TypeError::SortDepthExceeded { .. } => 6,
        rn::TypeError::Unsupported => 7,
    }
}

/// Payload-deep agreement between a native TypeError and a JIT TypeError —
/// incl. the NEW UnknownFVar id-identity (the stale-FVar observable).
fn type_error_agrees_nj(n: &rn::TypeError, j: &rn::TypeError) -> bool {
    if type_error_disc(n) != type_error_disc(j) {
        return false;
    }
    match (n, j) {
        (rn::TypeError::UnboundVariable(a), rn::TypeError::UnboundVariable(b)) => a == b,
        (rn::TypeError::UnknownFVar(a), rn::TypeError::UnknownFVar(b)) => a == b,
        (rn::TypeError::UnknownConst(a), rn::TypeError::UnknownConst(b)) => name_eq_nj(a, b),
        (
            rn::TypeError::TypeMismatch {
                expected: e1,
                inferred: i1,
            },
            rn::TypeError::TypeMismatch {
                expected: e2,
                inferred: i2,
            },
        ) => deep_eq_nj(e1, e2) && deep_eq_nj(i1, i2),
        (rn::TypeError::NotAPi { ty: t1 }, rn::TypeError::NotAPi { ty: t2 }) => deep_eq_nj(t1, t2),
        (rn::TypeError::ExpectedSort { ty: t1 }, rn::TypeError::ExpectedSort { ty: t2 }) => {
            deep_eq_nj(t1, t2)
        }
        (
            rn::TypeError::SortDepthExceeded { depth: a },
            rn::TypeError::SortDepthExceeded { depth: b },
        ) => a == b,
        _ => true,
    }
}

fn env_error_disc(e: &rn::EnvError) -> u8 {
    match e {
        rn::EnvError::TypeCheckFailed { .. } => 0,
        rn::EnvError::DuplicateLevelParam { .. } => 1,
        rn::EnvError::TheoremTypeNotProp { .. } => 2,
        rn::EnvError::ContainsFreeVar { .. } => 3,
        rn::EnvError::ContainsMetavar { .. } => 4,
        rn::EnvError::UndefinedLevelParam { .. } => 5,
    }
}

/// Payload-deep agreement between the native gate error and the JIT gate
/// error (the R6 comparator, with the TypeCheckFailed source now routed
/// through the FULL type_error_agrees_nj — incl. UnknownFVar).
fn env_error_agrees_nj(n: &rn::EnvError, j: &rn::EnvError) -> bool {
    if env_error_disc(n) != env_error_disc(j) {
        return false;
    }
    match (n, j) {
        (
            rn::EnvError::TypeCheckFailed {
                name: n1,
                source: s1,
            },
            rn::EnvError::TypeCheckFailed {
                name: n2,
                source: s2,
            },
        ) => name_eq_nj(n1, n2) && type_error_agrees_nj(s1, s2),
        (
            rn::EnvError::DuplicateLevelParam {
                name: n1,
                param: p1,
            },
            rn::EnvError::DuplicateLevelParam {
                name: n2,
                param: p2,
            },
        ) => name_eq_nj(n1, n2) && name_eq_nj(p1, p2),
        (
            rn::EnvError::TheoremTypeNotProp { name: n1, sort: s1 },
            rn::EnvError::TheoremTypeNotProp { name: n2, sort: s2 },
        ) => name_eq_nj(n1, n2) && level_eq_nj(s1, s2),
        (
            rn::EnvError::ContainsFreeVar { name: n1 },
            rn::EnvError::ContainsFreeVar { name: n2 },
        ) => name_eq_nj(n1, n2),
        (
            rn::EnvError::ContainsMetavar { name: n1 },
            rn::EnvError::ContainsMetavar { name: n2 },
        ) => name_eq_nj(n1, n2),
        (
            rn::EnvError::UndefinedLevelParam {
                name: n1,
                param: p1,
            },
            rn::EnvError::UndefinedLevelParam {
                name: n2,
                param: p2,
            },
        ) => name_eq_nj(n1, n2) && name_eq_nj(p1, p2),
        _ => false,
    }
}

// ── drivers ──────────────────────────────────────────────────────────────────

type FvGateFn = extern "C" fn(*mut Result<(), rn::EnvError>, *mut rn::Expr, u64);
type FvProbeFn = extern "C" fn(*mut Result<rn::Expr, rn::TypeError>, *mut rn::ProbeIds, u64);

fn jit_gate(f: FvGateFn, case: u64) -> (Result<(), rn::EnvError>, rn::Expr) {
    let mut res_slot = std::mem::MaybeUninit::<Result<(), rn::EnvError>>::uninit();
    let mut ty_slot = std::mem::MaybeUninit::<rn::Expr>::uninit();
    unsafe {
        f(res_slot.as_mut_ptr(), ty_slot.as_mut_ptr(), case);
        (res_slot.assume_init(), ty_slot.assume_init())
    }
}

/// The native gate oracle — the mirror root, host-compiled.
fn native_gate(case: u64) -> (Result<(), rn::EnvError>, rn::Expr) {
    let mut res_slot = std::mem::MaybeUninit::<Result<(), rn::EnvError>>::uninit();
    let mut ty_slot = std::mem::MaybeUninit::<rn::Expr>::uninit();
    unsafe {
        rn::fvar_gate_root(res_slot.as_mut_ptr(), ty_slot.as_mut_ptr(), case);
        (res_slot.assume_init(), ty_slot.assume_init())
    }
}

fn jit_probe(f: FvProbeFn, idx: u64) -> (Result<rn::Expr, rn::TypeError>, rn::ProbeIds) {
    let mut res_slot = std::mem::MaybeUninit::<Result<rn::Expr, rn::TypeError>>::uninit();
    let mut ids_slot = std::mem::MaybeUninit::<rn::ProbeIds>::uninit();
    unsafe {
        f(res_slot.as_mut_ptr(), ids_slot.as_mut_ptr(), idx);
        (res_slot.assume_init(), ids_slot.assume_init())
    }
}

/// The native probe oracle — the mirror root, host-compiled.
fn native_probe(idx: u64) -> (Result<rn::Expr, rn::TypeError>, rn::ProbeIds) {
    let mut res_slot = std::mem::MaybeUninit::<Result<rn::Expr, rn::TypeError>>::uninit();
    let mut ids_slot = std::mem::MaybeUninit::<rn::ProbeIds>::uninit();
    unsafe {
        rn::fvar_probe_root(res_slot.as_mut_ptr(), ids_slot.as_mut_ptr(), idx);
        (res_slot.assume_init(), ids_slot.assume_init())
    }
}

// Hand-built-name helper for pinned expectations (mirror machinery — the same
// fold production from_string performs).
fn hn1(s: &str) -> rn::Name {
    rn::fold_step(rn::name_anon(), s)
}

/// The case-17 declared type Π(α:Sort u).Π(α:Sort v). Sort u — the CORRECT
/// shadow-replay rebuild target (mirror-built).
fn decl17_declared_type() -> rn::Expr {
    match rn::build_decl_case(17) {
        rn::Declaration::Definition { type_, .. } => type_.as_ref().clone(),
        other => panic!("case 17 must be a Definition, got {other:?}"),
    }
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 1 — module sanity: both fixtures parse + validate 0; the ENTIRE FVar
// discipline is genuinely IN-MODULE (bodied): LocalContext push/push_let/pop/
// get/freshness_guard/new, open_bvar, abstract_fvar(_at), subst_fvar, the
// FVar-path infer core, plus the full R6 gate/universe/Name surface. The
// composition edges RUN (open→infer→close wired through the production
// pieces), the ARMED control fn is ABSENT from the gate module and confined
// to shadow_replay in the probe module.
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn fv_module_sanity_and_inmodule_surface() {
    for (text, what) in [
        (FV_GATE_TIR, "fvar_gate_root closure"),
        (FV_PROBE_TIR, "fvar_probe_root closure"),
    ] {
        let module = parse_and_validate(text, what);
        let bodied = |sym: &str| {
            module
                .functions
                .iter()
                .find(|f| f.name == sym)
                .map(|f| !f.blocks.is_empty())
                .unwrap_or(false)
        };
        // THE FVAR DISCIPLINE must be in-module in BOTH fixtures.
        for sym in [
            "LocalContext__new",
            "LocalContext__push",
            "LocalContext__push_let",
            "LocalContext__pop",
            "LocalContext__get",
            "LocalContext__freshness_guard",
            "Verifier____env___open_bvar",
            "Verifier____env___infer_type_core",
            "Expr__abstract_fvar",
            "Expr__abstract_fvar_at",
            "Expr__subst_fvar",
            "Expr__instantiate",
            // the real-Name machinery (R6 surface, unchanged):
            "name_anon",
            "name_str_part",
            "name_num_part",
            "murmur_hash_64a_idx",
            "mix_hash",
            "parse_u64_ascii",
            "fold_step",
            "name_eq",
            "hash_name",
            "hash_levels",
            "build_env",
            "ExprKind__compute_meta",
        ] {
            assert!(
                bodied(sym),
                "`{sym}` must be lowered in-module (bodied) in {what}"
            );
        }
    }

    // Gate fixture: the full gate + pillars + Level machinery bodied, and the
    // ARMED control fn STRUCTURALLY ABSENT.
    let module = parse_and_validate(FV_GATE_TIR, "fvar_gate_root closure");
    assert!(
        module
            .functions
            .iter()
            .all(|f| f.name != "LocalContext__push_forced_id_control"),
        "the ARMED-CONTROL push_forced_id_control must NOT be reachable from the gate root"
    );
    let bodied = |sym: &str| {
        module
            .functions
            .iter()
            .find(|f| f.name == sym)
            .map(|f| !f.blocks.is_empty())
            .unwrap_or(false)
    };
    for sym in [
        "Verifier____env___check_decl_readonly",
        "Verifier____env___infer_sort",
        "Verifier____env___infer_sort_inner",
        "Verifier____env___check_type",
        "Verifier____env___infer_type",
        "Verifier____env___whnf_impl",
        "Verifier____env___whnf_inner",
        "Verifier____env___is_def_eq",
        "Verifier____env___def_eq_inner",
        "Verifier____env___structural_eq",
        "Verifier____env___level_eq",
        "Verifier____env___unfold_const",
        "Expr__lift_at",
        "find_undef_level_param",
        "find_undef_level_param_in_level",
        "Level__is_def_eq",
        "Level__normalize",
        "Level__normalize_impl",
        "Level__normalize_max",
        "Level__is_norm_lt",
        "Level__imax",
        "Level__max",
        "Level__succ",
        "Level__is_zero",
        "name_cmp_is_lt",
        "str_bytes_cmp",
        "str_bytes_eq",
        "build_decl_case",
        "_Level_as_std__cmp__PartialEq___eq",
        "_Level_as_std__hash__Hash___hash",
    ] {
        assert!(bodied(sym), "`{sym}` must be lowered in-module (bodied)");
    }

    // ── CONFIRM the composition edges are RUNNING (not bypassed), by IR text.
    //    (Every edge below was pre-validated against the emitted text at
    //    harness-generation time; this re-checks from the parsed module.) ──
    let idx_of = |sym: &str| -> usize {
        module
            .functions
            .iter()
            .position(|f| f.name == sym)
            .unwrap_or_else(|| panic!("`{sym}` not in module"))
    };
    let body_of = |sym: &str| -> &str {
        let start = FV_GATE_TIR
            .find(&format!("fn @{sym}("))
            .unwrap_or_else(|| panic!("`{sym}` header present in IR text"));
        let after = &FV_GATE_TIR[start + 1..];
        let end = after
            .find("\nfn @")
            .map(|i| start + 1 + i)
            .unwrap_or(FV_GATE_TIR.len());
        &FV_GATE_TIR[start..end]
    };
    let edge = |caller: &str, callee: &str| {
        let b = body_of(caller);
        let i = idx_of(callee);
        assert!(
            b.contains(&format!("@func.{i}(")),
            "`{caller}` must Call @func.{i} = `{callee}` — the composition edge must RUN"
        );
    };
    // THE OPEN→INFER→CLOSE DISCIPLINE, wired end-to-end:
    edge("Verifier____env___infer_type_core", "LocalContext__push");
    edge(
        "Verifier____env___infer_type_core",
        "LocalContext__push_let",
    );
    edge("Verifier____env___infer_type_core", "LocalContext__pop");
    edge("Verifier____env___infer_type_core", "LocalContext__get");
    edge(
        "Verifier____env___infer_type_core",
        "Verifier____env___open_bvar",
    );
    edge("Verifier____env___infer_type_core", "Expr__abstract_fvar");
    edge("Verifier____env___infer_type_core", "Expr__subst_fvar");
    edge("Verifier____env___open_bvar", "Expr__instantiate");
    edge("LocalContext__push", "LocalContext__freshness_guard");
    edge("LocalContext__push_let", "LocalContext__freshness_guard");
    edge("Expr__abstract_fvar", "Expr__abstract_fvar_at");
    // §5's Pi fallback opens with a fresh FVar too:
    edge(
        "Verifier____env___infer_sort_inner",
        "Verifier____env___infer_type_core",
    );
    edge("Verifier____env___infer_sort_inner", "LocalContext__push");
    edge(
        "Verifier____env___infer_sort_inner",
        "Verifier____env___open_bvar",
    );
    edge("Verifier____env___infer_sort_inner", "LocalContext__pop");
    edge("Verifier____env___infer_sort_inner", "Level__imax");
    // the gate composes §2..§7 and creates the SHARED context:
    edge("Verifier____env___check_decl_readonly", "LocalContext__new");
    edge("Verifier____env___check_decl_readonly", "name_eq");
    edge(
        "Verifier____env___check_decl_readonly",
        "find_undef_level_param",
    );
    edge(
        "Verifier____env___check_decl_readonly",
        "Verifier____env___infer_sort",
    );
    edge("Verifier____env___check_decl_readonly", "Level__is_zero");
    edge(
        "Verifier____env___check_decl_readonly",
        "Verifier____env___check_type",
    );
    // the R6 universe/Name surface (unchanged, re-confirmed):
    edge("Verifier____env___level_eq", "Level__is_def_eq");
    edge("Verifier____env___structural_eq", "name_eq");
    edge("Verifier____env___unfold_const", "name_eq");
    edge("find_undef_level_param_in_level", "name_eq");
    edge("_Level_as_std__cmp__PartialEq___eq", "name_eq");
    edge("Level__is_norm_lt", "name_cmp_is_lt");
    edge("name_cmp_is_lt", "str_bytes_cmp");
    edge("name_eq", "str_bytes_eq");
    edge("ExprKind__compute_meta", "hash_name");
    edge("ExprKind__compute_meta", "hash_levels");
    edge("name_str_part", "murmur_hash_64a_idx");
    edge("name_str_part", "mix_hash");
    edge("fold_step", "parse_u64_ascii");
    edge("fold_step", "name_num_part");
    edge("fold_step", "name_str_part");

    // Probe fixture: the ARMED control fn is confined to shadow_replay.
    let pmodule = parse_and_validate(FV_PROBE_TIR, "fvar_probe_root closure");
    let p_idx_of = |sym: &str| -> usize {
        pmodule
            .functions
            .iter()
            .position(|f| f.name == sym)
            .unwrap_or_else(|| panic!("`{sym}` not in probe module"))
    };
    let p_body_of = |sym: &str| -> &str {
        let start = FV_PROBE_TIR
            .find(&format!("fn @{sym}("))
            .unwrap_or_else(|| panic!("`{sym}` header present in probe IR text"));
        let after = &FV_PROBE_TIR[start + 1..];
        let end = after
            .find("\nfn @")
            .map(|i| start + 1 + i)
            .unwrap_or(FV_PROBE_TIR.len());
        &FV_PROBE_TIR[start..end]
    };
    let ctl = p_idx_of("LocalContext__push_forced_id_control");
    let callers: Vec<&str> = pmodule
        .functions
        .iter()
        .map(|f| f.name.as_str())
        .filter(|s| p_body_of(s).contains(&format!("@func.{ctl}(")))
        .collect();
    assert_eq!(
        callers,
        vec!["shadow_replay"],
        "push_forced_id_control must be called ONLY by the armed shadow_replay"
    );
    // the CORRECT-path replay runs the production open→infer→close pieces:
    for callee in [
        "LocalContext__push",
        "Verifier____env___open_bvar",
        "Verifier____env___infer_type_core",
        "Expr__abstract_fvar",
        "LocalContext__pop",
    ] {
        let i = p_idx_of(callee);
        assert!(
            p_body_of("shadow_replay").contains(&format!("@func.{i}(")),
            "shadow_replay must call `{callee}`"
        );
    }
    // the armed 1723-corruption target exists EXACTLY once per module:
    assert_eq!(
        FV_PROBE_TIR.matches("const u64 1723").count(),
        1,
        "the anon-hash seed must appear exactly once in the probe module (name_anon)"
    );
    assert_eq!(FV_GATE_TIR.matches("const u64 1723").count(), 1);
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 2 — THE FVAR-DISCIPLINE PROBES, native == JIT at full payload depth:
// stale-FVar UnknownFVar production-error identity (ids intact), monotonic
// no-reuse after pop, the shadow replay with DISTINCT fresh ids asserted
// in-module, the ARMED id-collision control (guards trip, result DIVERGES to
// the pinned kernel-`v` witness — deterministically, native==JIT on the
// broken path too), the abstract↔open round-trip, and the dependent Pi.
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn fv_probe_fvar_discipline_differential() {
    let buffer = run_with_watchdog("JIT compile fvar_probe_root", move || {
        jit_module(FV_PROBE_TIR, "fvar_probe_root closure", &fv_externs())
    });
    let probe: FvProbeFn = unsafe { std::mem::transmute(bind(&buffer, "fvar_probe_root")) };

    let labels: [&str; 7] = [
        "STALE-FVAR empty ctx: FVar(7) => UnknownFVar(7)",
        "POPPED-DECL stale + monotonic no-reuse: ids (0, then fresh 1)",
        "NONEMPTY ctx missing id: FVar(99) => UnknownFVar(99)",
        "SHADOW replay CORRECT: distinct ids (0,1), rebuilt ...Sort u",
        "SHADOW replay ARMED-COLLIDED: reused id 0, guards trip, rebuilt ...Sort v",
        "ABSTRACT<->OPEN round-trip identity (flags=7)",
        "DEPENDENT Pi: body sort via opened-FVar ctx lookup",
    ];

    let mut jit_out: Vec<(Result<rn::Expr, rn::TypeError>, rn::ProbeIds)> = Vec::new();
    for idx in 0u64..7 {
        let (nres, nids) = native_probe(idx);
        let (jres, jids) = jit_probe(probe, idx);
        // scalar observables: minted ids, guard trips, in-module flags —
        // ALL must agree native==JIT.
        assert_eq!(
            (nids.id0, nids.id1, nids.guard_trips, nids.flags),
            (jids.id0, jids.id1, jids.guard_trips, jids.flags),
            "probe {idx} `{}`: ProbeIds disagree native vs JIT",
            labels[idx as usize]
        );
        // result: deep payload agreement (Ok exprs meta-bit-identical;
        // errors variant + payload identical — incl. UnknownFVar ids).
        let agree = match (&nres, &jres) {
            (Ok(a), Ok(b)) => deep_eq_nj(a, b),
            (Err(a), Err(b)) => type_error_agrees_nj(a, b),
            _ => false,
        };
        assert!(
            agree,
            "probe {idx} `{}`: result disagrees native vs JIT:\n  native = {nres:?}\n  jit    = {jres:?}",
            labels[idx as usize]
        );
        jit_out.push((jres, jids));
    }

    // ── HARD PINS (production identity, asserted on the JIT outputs) ──
    // 0: the production stale-FVar error with the id payload INTACT.
    match &jit_out[0].0 {
        Err(rn::TypeError::UnknownFVar(rn::FVarId(7))) => {}
        other => panic!("probe 0 must be Err(UnknownFVar(FVarId(7))), got {other:?}"),
    }
    assert_eq!(jit_out[0].1.guard_trips, 0);
    // 1: popped decl => UnknownFVar(0); the NEXT push mints id 1 — popped ids
    // are NEVER reused (the monotonic counter, #1773).
    match &jit_out[1].0 {
        Err(rn::TypeError::UnknownFVar(rn::FVarId(0))) => {}
        other => panic!("probe 1 must be Err(UnknownFVar(FVarId(0))), got {other:?}"),
    }
    assert_eq!(
        (jit_out[1].1.id0, jit_out[1].1.id1),
        (0, 1),
        "pop must NOT recycle id 0"
    );
    assert_eq!(
        jit_out[1].1.flags, 1,
        "in-module distinctness assert must hold"
    );
    // 2: nonempty context missing the id — error id EXACTLY 99.
    match &jit_out[2].0 {
        Err(rn::TypeError::UnknownFVar(rn::FVarId(99))) => {}
        other => panic!("probe 2 must be Err(UnknownFVar(FVarId(99))), got {other:?}"),
    }
    assert_eq!(jit_out[2].1.guard_trips, 0);
    // 3: CORRECT shadow replay — two opens of SAME-NAMED (anon) binders mint
    // DISTINCT fresh ids (0,1) — asserted IN-MODULE (flags) and here — no
    // guard trips, and the rebuilt type IS the declared case-17 type
    // Π(α:Sort u).Π(α:Sort v). Sort u (meta-bit-identical to the mirror).
    let (res3, ids3) = &jit_out[3];
    assert_eq!(
        (ids3.id0, ids3.id1, ids3.guard_trips, ids3.flags),
        (0, 1, 0, 1)
    );
    let rebuilt3 = match res3 {
        Ok(e) => e,
        other => panic!("probe 3 must be Ok(rebuilt), got {other:?}"),
    };
    let want = decl17_declared_type();
    assert!(
        deep_eq_nj(&want, rebuilt3),
        "probe 3: the CORRECT replay must rebuild the declared type Π.Π.Sort u"
    );
    // 4: THE ARMED ID-COLLISION CONTROL — freshness broken on purpose:
    //   * both production freshness asserts would have fired: guard_trips == 2,
    //   * the ids are NOT distinct (in-module flags == 0),
    //   * the rebuilt type DIVERGES from the correct one,
    //   * the divergence is EXACTLY the shadow-capture: the body resolves to
    //     the INNER binder's domain — ...Sort v, its Param name decoding to
    //     the kernel `v` golden.
    // Freshness is load-bearing and observable — and deterministic (the
    // native==JIT agreement was already asserted in the loop above).
    let (res4, ids4) = &jit_out[4];
    assert_eq!(
        (ids4.id0, ids4.id1),
        (0, 0),
        "the armed control must reuse id 0"
    );
    assert_eq!(
        ids4.guard_trips, 2,
        "BOTH production freshness guards must trip"
    );
    assert_eq!(
        ids4.flags, 0,
        "the in-module distinctness assert must FAIL under collision"
    );
    let rebuilt4 = match res4 {
        Ok(e) => e,
        other => panic!("probe 4 must be Ok(divergent rebuild), got {other:?}"),
    };
    assert!(
        !deep_eq_nj(&want, rebuilt4),
        "ARMED CONTROL FAILED: the collided replay rebuilt the CORRECT type — freshness would be vacuous"
    );
    match &rebuilt4.kind {
        rn::ExprKind::Pi(_, _, inner) => match &inner.kind {
            rn::ExprKind::Pi(_, _, body) => match &body.kind {
                rn::ExprKind::Sort(rn::Level::Param(n)) => {
                    let (_, h, _) = unsafe { decode_jit_name(n as *const rn::Name as *const u8) };
                    assert_eq!(
                        h, GOLDEN_V,
                        "probe 4: the collided body must resolve to the INNER domain Sort v (kernel `v` golden)"
                    );
                }
                other => panic!("probe 4 body must be Sort(Param v), got {other:?}"),
            },
            other => panic!("probe 4 inner must be Pi, got {other:?}"),
        },
        other => panic!("probe 4 rebuilt must be Pi, got {other:?}"),
    }
    // and the CORRECT body resolves to Sort u — the pair (u vs v) is the
    // whole freshness observable:
    match &rebuilt3.kind {
        rn::ExprKind::Pi(_, _, inner) => match &inner.kind {
            rn::ExprKind::Pi(_, _, body) => match &body.kind {
                rn::ExprKind::Sort(rn::Level::Param(n)) => {
                    let (_, h, _) = unsafe { decode_jit_name(n as *const rn::Name as *const u8) };
                    assert_eq!(
                        h, GOLDEN_U,
                        "probe 3 body must resolve to the OUTER domain Sort u"
                    );
                }
                other => panic!("probe 3 body must be Sort(Param u), got {other:?}"),
            },
            other => panic!("probe 3 inner must be Pi, got {other:?}"),
        },
        other => panic!("probe 3 rebuilt must be Pi, got {other:?}"),
    }
    // 5: the round-trip contract held IN-MODULE (flags bit0: structural
    // roundtrip == e; bit1: the abstracted term has NO FVar left; bit2:
    // meta-bit identity) and the abstracted term's has_fvar quick bit is
    // CLEAR on the JIT-built value.
    let (res5, ids5) = &jit_out[5];
    assert_eq!(ids5.flags, 7, "round-trip flags must be 0b111");
    let abstracted = match res5 {
        Ok(e) => e,
        other => panic!("probe 5 must be Ok(abstracted), got {other:?}"),
    };
    assert_eq!(
        (abstracted.meta.raw() >> 40) & 1,
        0,
        "probe 5: abstract_fvar must ERASE the FVar (has_fvar quick bit clear)"
    );
    // and the abstraction really turned the FVars into the right BVars:
    match &abstracted.kind {
        rn::ExprKind::App(f, lam) => {
            match &f.kind {
                rn::ExprKind::App(_, arg) => assert!(
                    matches!(&arg.kind, rn::ExprKind::BVar(0)),
                    "probe 5: the depth-0 FVar must become BVar(0)"
                ),
                other => panic!("probe 5 fn side must be App, got {other:?}"),
            }
            match &lam.kind {
                rn::ExprKind::Lam(_, _, body) => match &body.kind {
                    rn::ExprKind::App(bf, ba) => {
                        assert!(
                            matches!(&bf.kind, rn::ExprKind::BVar(1)),
                            "probe 5: the under-binder FVar must become BVar(1) (depth-shifted)"
                        );
                        assert!(
                            matches!(&ba.kind, rn::ExprKind::BVar(0)),
                            "probe 5: the existing bound BVar(0) must stay BVar(0)"
                        );
                    }
                    other => panic!("probe 5 lam body must be App, got {other:?}"),
                },
                other => panic!("probe 5 rhs must be Lam, got {other:?}"),
            }
        }
        other => panic!("probe 5 abstracted must be App, got {other:?}"),
    }
    // 6: the dependent-Pi inferred sort — EXACTLY
    // Max(succ u, Max(u, succ v)) (the smart-imax composition whose inner
    // level came from the opened FVar's context type).
    let res6 = match &jit_out[6].0 {
        Ok(e) => e.clone(),
        other => panic!("probe 6 must be Ok(Sort ..), got {other:?}"),
    };
    let expected6 = rn::Level::Max(
        Arc::new(rn::Level::Succ(Arc::new(rn::Level::Param(hn1("u"))))),
        Arc::new(rn::Level::Max(
            Arc::new(rn::Level::Param(hn1("u"))),
            Arc::new(rn::Level::Succ(Arc::new(rn::Level::Param(hn1("v"))))),
        )),
    );
    match &res6.kind {
        rn::ExprKind::Sort(l) => assert!(
            level_eq_nj(&expected6, l),
            "probe 6: inferred sort must be Max(succ u, Max(u, succ v)); got {l:?}"
        ),
        other => panic!("probe 6 must return a Sort, got {other:?}"),
    }

    drop(buffer);
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 3 — the FULL decl-gate differential THROUGH THE FVAR PATH: the R6
// 16-case set (same verdicts, same payload depth — REAL-Name payloads raw-
// decoded + chain-revalidated, expr payloads meta-bit-identical) + the two
// R8 cases (zeta/let, shadowing) = 8 accepts / 10 rejects, native == JIT on
// every verdict and every payload. R6's pinned witnesses re-asserted; the
// R6-style fail-loud negative controls re-armed.
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn fv_decl_gate_full_differential() {
    let buffer = run_with_watchdog("JIT compile fvar_gate_root", move || {
        jit_module(FV_GATE_TIR, "fvar_gate_root closure", &fv_externs())
    });
    let gate: FvGateFn = unsafe { std::mem::transmute(bind(&buffer, "fvar_gate_root")) };

    let labels: [&str; 18] = [
        "ACCEPT ax.polymax{u,v} : Sort(max u v)",
        "REJECT §6 thm.polymax{u,v} [sort=succ(max u v) not Prop]",
        "REJECT §4 ax.nested{u} [undef v inside IMax]",
        "REJECT §2 ax.dup{u,v,u} [duplicate param u — REAL name_eq]",
        "ACCEPT thm.prop : (∀α:Prop. α→α) := λλ#0 [imax(_,0)=0; §7 open→infer→close towers]",
        "REJECT §6 thm.poly{u} [sort=IMax(succ u,u) not Prop]",
        "ACCEPT def.commute{u,v} [§7 Max commutativity]",
        "ACCEPT def.dedup{u,v} [imax->Max + dedup; §5+§7 FVar opens]",
        "REJECT §7 def.wrong{u,v} [wrong universe — TypeMismatch payloads]",
        "REJECT §5 ax.notatype [ExpectedSort — payload Const(Nat)]",
        "REJECT §3 ax.fvar : FVar(5) [ContainsFreeVar]",
        "ACCEPT opq.poly{u}",
        "ACCEPT ax.constty [env unfold + infer_sort Pi arm — FVar-opened]",
        "REJECT §4 def.valundef{v} [undef u in value]",
        "REJECT §4 ax.constlvls{u} [undef v inside Const LEVELS]",
        "REJECT §2 thm.42{u,u} [dup param; decl name carries a REAL Num part]",
        "ACCEPT def.zeta [R8: ctx_push_let + FVar-typed λ domain + OBSERVABLE zeta subst]",
        "ACCEPT def.shadow [R8: same-name binders, lookup past innermost decl]",
    ];

    let mut accepts = 0usize;
    let mut rejects = 0usize;
    let mut jit_results: Vec<Result<(), rn::EnvError>> = Vec::new();
    for case in 0u64..18 {
        let label = labels[case as usize];
        let (native, nty) = native_gate(case);
        let (jit, jty) = jit_gate(gate, case);
        // The declared TYPE built by JIT machine code must be
        // meta-bit-identical to the native mirror build at every node.
        assert!(
            deep_eq_nj(&nty, &jty),
            "case {case} `{label}`: JIT-built declared type must be meta-bit-identical to native"
        );
        match (&native, &jit) {
            (Ok(()), Ok(())) => accepts += 1,
            (Err(ne), Err(je)) => {
                assert!(
                    env_error_agrees_nj(ne, je),
                    "decl gate JIT disagrees with native on `{label}` (both Err, payloads differ):\n  native = {ne:?}\n  jit    = {je:?}"
                );
                rejects += 1;
            }
            _ => panic!(
                "decl gate JIT vs native ACCEPT/REJECT disagreement on `{label}`:\n  native = {native:?}\n  jit    = {jit:?}"
            ),
        }
        jit_results.push(jit);
    }
    assert_eq!(
        accepts, 8,
        "expected exactly 8 ACCEPTs (0,4,6,7,11,12,16,17)"
    );
    assert_eq!(rejects, 10, "expected exactly 10 REJECTs");

    // ── R6 pinned witnesses, re-asserted through the FVar path. ──
    // Case 5: sort must be EXACTLY IMax(Succ(Param u), Param u).
    let expected_imax = rn::Level::IMax(
        Arc::new(rn::Level::Succ(Arc::new(rn::Level::Param(hn1("u"))))),
        Arc::new(rn::Level::Param(hn1("u"))),
    );
    let jit5_sort = match &jit_results[5] {
        Err(rn::EnvError::TheoremTypeNotProp { sort, .. }) => sort.clone(),
        other => panic!("case 5 must be TheoremTypeNotProp, got {other:?}"),
    };
    assert!(
        level_eq_nj(&expected_imax, &jit5_sort),
        "case 5: JIT-built sort payload must be IMax(succ u, u); got {jit5_sort:?}"
    );
    // Case 8: TypeMismatch with the wrong-universe witness Sort(succ(..)).
    let (j8_exp, j8_inf) = match &jit_results[8] {
        Err(rn::EnvError::TypeCheckFailed {
            source: rn::TypeError::TypeMismatch { expected, inferred },
            ..
        }) => (expected.clone(), inferred.clone()),
        other => panic!("case 8 JIT must be TypeMismatch, got {other:?}"),
    };
    assert!(
        matches!(&j8_inf.kind, rn::ExprKind::Sort(rn::Level::Succ(_))),
        "case 8: the JIT-built inferred type must be Sort(succ(..))"
    );
    // Case 9: ExpectedSort payload = the JIT-built Const("Nat"), kernel golden.
    match &jit_results[9] {
        Err(rn::EnvError::TypeCheckFailed {
            source: rn::TypeError::ExpectedSort { ty },
            ..
        }) => match &ty.kind {
            rn::ExprKind::Const(n, levels) => {
                assert!(levels.is_empty(), "case 9: Const(Nat) must carry no levels");
                let (comps, h, _) = unsafe { decode_jit_name(n as *const rn::Name as *const u8) };
                assert_eq!(
                    h, GOLDEN_NAT,
                    "case 9: the Lit-rule type name must be the kernel `Nat` golden"
                );
                assert_eq!(comps, vec![Comp::Str(b"Nat".to_vec())]);
            }
            other => panic!("case 9 payload must be Const(Nat), got {other:?}"),
        },
        other => panic!("case 9 must be ExpectedSort, got {other:?}"),
    }
    // Case 3: DuplicateLevelParam payload decodes to kernel goldens.
    match &jit_results[3] {
        Err(rn::EnvError::DuplicateLevelParam { name, param }) => {
            let (_, nh, _) = unsafe { decode_jit_name(name as *const rn::Name as *const u8) };
            assert_eq!(
                nh, GOLDEN_AX_DUP,
                "case 3: decl-name hash must be the `ax.dup` golden"
            );
            let (_, ph, _) = unsafe { decode_jit_name(param as *const rn::Name as *const u8) };
            assert_eq!(
                ph, GOLDEN_U,
                "case 3: the duplicate param must decode to the `u` golden"
            );
        }
        other => panic!("case 3 must be DuplicateLevelParam, got {other:?}"),
    }
    // Case 15: the Num-part decl name (thm.42), field-reordered decode LIVE.
    match &jit_results[15] {
        Err(rn::EnvError::DuplicateLevelParam { name, .. }) => {
            let (ncomps, nh, _) = unsafe { decode_jit_name(name as *const rn::Name as *const u8) };
            assert_eq!(
                nh, GOLDEN_THM42,
                "case 15: decl-name hash must be the `thm.42` golden"
            );
            assert_eq!(ncomps, vec![Comp::Num(42), Comp::Str(b"thm".to_vec())]);
        }
        other => panic!("case 15 must be DuplicateLevelParam, got {other:?}"),
    }
    // Case 14: the undef param found inside Const LEVELS must be `v`.
    match &jit_results[14] {
        Err(rn::EnvError::UndefinedLevelParam { param, .. }) => {
            let (_, ph, _) = unsafe { decode_jit_name(param as *const rn::Name as *const u8) };
            assert_eq!(
                ph, GOLDEN_V,
                "case 14: the undef param inside Const levels must be `v`"
            );
        }
        other => panic!("case 14 must be UndefinedLevelParam, got {other:?}"),
    }
    // ── R8 pins: the new cases really are the FVar-discipline accepts. ──
    assert!(jit_results[16].is_ok(), "case 16 (zeta/let) must ACCEPT");
    assert!(jit_results[17].is_ok(), "case 17 (shadowing) must ACCEPT");
    // and their JIT-built declared types have the pinned shapes:
    let (_, jty16) = jit_gate(gate, 16);
    match &jty16.kind {
        rn::ExprKind::Pi(_, dom, _) => assert!(
            matches!(&dom.kind, rn::ExprKind::Sort(rn::Level::Zero)),
            "case 16 declared type must be Pi(Sort 0, Sort 0)"
        ),
        other => panic!("case 16 declared type must be Pi, got {other:?}"),
    }
    let (_, jty17) = jit_gate(gate, 17);
    assert!(
        deep_eq_nj(&decl17_declared_type(), &jty17),
        "case 17 declared type must be Π(α:Sort u).Π(α:Sort v). Sort u"
    );

    // ── NC1 (fail-loud): an always-accept gate must DISAGREE with native on
    //    the wrong-universe definition. ──
    let (native8, _) = native_gate(8);
    assert!(
        native8.is_err(),
        "control: native gate MUST reject the wrong-universe definition"
    );
    let always_accept = |_c: u64| -> Result<(), rn::EnvError> { Ok(()) };
    let bogus = always_accept(8);
    assert_ne!(
        native8.is_ok(),
        bogus.is_ok(),
        "NEGATIVE CONTROL FAILED: an always-accept gate agreed with native"
    );
    // ── NC2 (fail-loud): wrong universe expectations must be REJECTED. ──
    assert!(
        !level_eq_nj(&rn::Level::Zero, &jit5_sort),
        "NEGATIVE CONTROL FAILED: comparator equated IMax(succ u, u) with Zero"
    );
    let crossed_imax = rn::Level::IMax(
        Arc::new(rn::Level::Succ(Arc::new(rn::Level::Param(hn1("v"))))),
        Arc::new(rn::Level::Param(hn1("v"))),
    );
    assert!(
        !level_eq_nj(&crossed_imax, &jit5_sort),
        "NEGATIVE CONTROL FAILED: comparator equated IMax(succ u, u) with IMax(succ v, v)"
    );
    // ── NC3 (fail-loud): a meta-word-corrupted copy must be REJECTED by
    //    deep_eq_nj (the bit-identity check reads meta). ──
    let corrupted = rn::Expr {
        kind: j8_exp.kind.clone(),
        meta: rn::ExprMeta(j8_exp.meta.raw() ^ 1),
    };
    assert!(
        !deep_eq_nj(&corrupted, &j8_exp),
        "NEGATIVE CONTROL FAILED: deep_eq_nj accepted a meta-corrupted expr"
    );

    drop(buffer);
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 4 — ARMED MODULE-TEXT CORRUPTION: flip the anon-hash seed constant in
// the probe module's MACHINE CODE source (`const u64 1723` -> 1724, the one
// occurrence inside name_anon), re-JIT, and assert every constructed Name's
// hash diverges EXACTLY as the production chain predicts
// (mix(1724, murmur("u", 11))) while the DISCIPLINE observables (fresh ids,
// guard trips) stay intact — the hash chain runs IN the JIT machine code and
// the golden pins are not vacuous.
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn fv_armed_module_corruption_diverges() {
    assert_eq!(FV_PROBE_TIR.matches("const u64 1723").count(), 1);
    let corrupted_text = FV_PROBE_TIR.replace("const u64 1723", "const u64 1724");
    assert_ne!(corrupted_text, FV_PROBE_TIR);

    let buffer = run_with_watchdog("JIT compile CORRUPTED fvar_probe_root", move || {
        jit_module(
            &corrupted_text,
            "CORRUPTED fvar_probe_root closure",
            &fv_externs(),
        )
    });
    let probe: FvProbeFn = unsafe { std::mem::transmute(bind(&buffer, "fvar_probe_root")) };

    // Probe 3 (the CORRECT shadow replay): the DISCIPLINE is untouched by the
    // hash corruption — ids (0,1), no guard trips, in-module distinctness
    // holds…
    let (res3, ids3) = jit_probe(probe, 3);
    assert_eq!(
        (ids3.id0, ids3.id1, ids3.guard_trips, ids3.flags),
        (0, 1, 0, 1),
        "corruption must NOT affect the freshness discipline (ids/guards)"
    );
    // …but every constructed Name hash DIVERGES, exactly as predicted.
    let rebuilt = match &res3 {
        Ok(e) => e,
        other => panic!("corrupted probe 3 must still be Ok(rebuilt), got {other:?}"),
    };
    let u_name = match &rebuilt.kind {
        rn::ExprKind::Pi(_, dom, _) => match &dom.kind {
            rn::ExprKind::Sort(rn::Level::Param(n)) => n,
            other => panic!("outer domain must be Sort(Param u), got {other:?}"),
        },
        other => panic!("rebuilt must be Pi, got {other:?}"),
    };
    // RAW decode (no chain revalidation — the chain is INTENTIONALLY broken).
    let read_u64 = |p: *const u8| -> u64 { unsafe { (p as *const u64).read_unaligned() } };
    let h = read_u64(unsafe { (u_name as *const rn::Name as *const u8).add(32) });
    assert_ne!(
        h, GOLDEN_U,
        "ARMED CONTROL FAILED: the corrupted module still produced the kernel `u` golden — the 1723 seed is not live in machine code"
    );
    let predicted = native_mix_hash(1724, native_murmur_hash_64a(b"u", 11));
    assert_eq!(
        h, predicted,
        "the corrupted hash must diverge EXACTLY as the production chain predicts (seed 1724)"
    );
    // and the UNCORRUPTED prediction is the golden — the oracle is sharp.
    assert_eq!(
        native_mix_hash(GOLDEN_ANON, native_murmur_hash_64a(b"u", 11)),
        GOLDEN_U
    );

    drop(buffer);
}
